paramsDict = {'assetId': value['params']['assetId'], 'startDate': value['params']['startDate'], 'endDate': value['params']['endDate']}
data = system.kanoa.utilities.convertDatasetToJSON(system.kanoa.event.getCounterEventTotals(paramsDict))

allCounts = {k: [] for k,v in value['counters'].items()}

for row in data:
	row['startDate'] = value['params']['startDate']
	row['endDate'] = value['params']['endDate']
	row['assetId'] = value['params']['assetId']			

	if row['counterTypeName'] == 'outfeed': allCounts['outfeed'].append(dict(row))
	elif row['counterTypeName'] == 'infeed': allCounts['infeed'].append(dict(row))
	elif row['counterTypeName'] == 'waste': allCounts['waste'].append(dict(row))
	elif row['counterTypeName'] == 'general': allCounts[row['counterName']].append(dict(row))
	else:
		if allCounts.has_key(row['counterName']): allCounts[row['counterName']].append(dict(row))
		else: allCounts[row['counterName']] = [dict(row)]

return allCounts

def addDefaultState(counterTypeId, counterId):
	return {
				"itemStateId": None,
	  			"itemStateColor": "#D5D5D5",
				"counterTypeId": counterTypeId,
				"itemStateClassPath": "",
	  			"counterId": counterId,
	  			"enabled": True,
				"itemStateName": "Add",
				"itemStateClassId": None
	}

if not value['assetId']: return {}

