data = system.kanoa.utilities.convertDatasetToJSON(system.kanoa.item.getAssetItemStates({'assetId': value['assetId']}))

self.custom.assetItemStates = data

for k,v in counters.items(): counters[k]['states'] = []

for row in data:
	row = dict(row)
	counter = row['counterTypeName']
	if counter:
		for k,v in counters.items():
			system.perspective.print("%s %s %s"%(k, v['counterTypeName'], counter))

			if v['counterTypeName'] == counter:
				row['counterId'] = v['counterId']
				counterName = v['counterName']
				system.perspective.print("Setting counter %s %s row to %s"%(counterName, row['itemStateName'], row['counterId']))
				counters[counterName]['states'].append(dict(row))
	else:
		system.perspective.print("HAS NO COUNTER")
		for k,v in counters.items():
			row['counterId'] = counters[k]['counterId']
			system.perspective.print("Setting counter %s %s row to %s"%(k, row['itemStateName'], row['counterId']))
			counters[k]['states'].append(dict(row))

for k,v in counters.items():
	if len(counters[k]['states']) == 0: counters[k]['states'].append(addDefaultState(v['counterTypeId'], v['counterId']))

return counters

