countInfo = payload['value']
if payload['change'] == 'delete': 
	self.deleteCounts(countInfo )
elif payload['change'] == 'update':
	self.saveCounts(countInfo, countInfo)
elif payload['change'] == 'add':
	self.updateCounts(countInfo)

else:
	return

